-- GATED, additive foundation only. Not part of the automatic migration sequence.
-- Requires 001–015 + 024 or their reviewed reconciled successors and VERIFIED recovery.
-- No owner is automatically enrolled. No worker, financial mutation or messaging operation.
begin;
create table public.botgen_owners(
 user_id uuid primary key references auth.users(id) on delete restrict,
 singleton boolean not null default true unique check(singleton),
 created_at timestamptz not null default now()
);
create function public.botgen_is_owner() returns boolean
language sql stable security definer set search_path=public as $$
 select coalesce(public.admin_role()='super_admin' and exists(select 1 from public.botgen_owners where user_id=auth.uid())
 and exists(select 1 from auth.users where id=auth.uid() and email_confirmed_at is not null and (banned_until is null or banned_until<now()))
 and not exists(select 1 from public.account_restrictions where user_id=auth.uid()),false)
$$;
create table public.botgen_templates(
 id text primary key, name text not null, category text not null, description text not null,
 features jsonb not null, fields jsonb not null, permissions jsonb not null,
 handler text unique not null, documentation text not null,
 status text not null check(status='CONFIGURATION_ONLY')
);
create table public.botgen_bots(
 id uuid primary key, owner_id uuid not null references public.botgen_owners(user_id) on delete restrict,
 template_id text not null references public.botgen_templates(id),
 name text not null check(length(trim(name)) between 3 and 80),
 configuration jsonb not null check(jsonb_typeof(configuration)='object' and octet_length(configuration::text)<=10000),
 status text not null default 'CONFIGURED' check(status='CONFIGURED'),
 created_at timestamptz not null default now(), updated_at timestamptz not null default now()
);
create index botgen_bots_owner_created on public.botgen_bots(owner_id,created_at desc,id);
create table public.botgen_audit(
 id uuid primary key default gen_random_uuid(), actor_id uuid not null references auth.users(id),
 bot_id uuid not null, action text not null check(action in ('created','configured','deleted')),
 created_at timestamptz not null default now()
);
create index botgen_audit_time on public.botgen_audit(created_at desc);
do $$declare t text;begin foreach t in array array['botgen_owners','botgen_templates','botgen_bots','botgen_audit'] loop
 execute format('alter table public.%I enable row level security',t);
 execute format('revoke all on public.%I from public,anon,authenticated,service_role',t);
end loop;end$$;
create policy botgen_template_read on public.botgen_templates for select to authenticated using(public.botgen_is_owner());
create policy botgen_bots_read on public.botgen_bots for select to authenticated using(public.botgen_is_owner() and owner_id=auth.uid());
create policy botgen_audit_read on public.botgen_audit for select to authenticated using(public.botgen_is_owner());
grant select on public.botgen_templates,public.botgen_bots,public.botgen_audit to authenticated;
create function public.botgen_save(p_id uuid,p_template text,p_name text,p_configuration jsonb) returns uuid
language plpgsql security definer set search_path=public as $$
declare spec public.botgen_templates; field jsonb; k text; existing public.botgen_bots;
begin
 if not public.botgen_is_owner() then raise exception 'Permission denied' using errcode='42501';end if;
 if p_id is null or p_name is null or length(trim(p_name)) not between 3 and 80 or p_configuration is null or jsonb_typeof(p_configuration)<>'object' or octet_length(p_configuration::text)>10000 then raise exception 'Invalid bot configuration';end if;
 select * into spec from public.botgen_templates where id=p_template;
 if not found then raise exception 'Unknown template';end if;
 for k in select jsonb_object_keys(p_configuration) loop
  if not exists(select 1 from jsonb_array_elements(spec.fields) f where f->>'key'=k) then raise exception 'Unsupported configuration field';end if;
 end loop;
 for field in select * from jsonb_array_elements(spec.fields) loop
  k=field->>'key';
  if jsonb_typeof(p_configuration->k) is distinct from 'string' or length(trim(p_configuration->>k)) not between 1 and 2000 then raise exception 'Required configuration field is invalid';end if;
 end loop;
 -- Serialize idempotent saves on the same UUID, including first insert.
 perform pg_advisory_xact_lock(hashtextextended(p_id::text,0));
 select * into existing from public.botgen_bots where id=p_id for update;
 if found and (existing.owner_id<>auth.uid() or existing.template_id<>p_template) then raise exception 'Bot ownership or template mismatch' using errcode='42501';end if;
 if found and existing.name=trim(p_name) and existing.configuration=p_configuration then return p_id;end if;
 insert into public.botgen_bots(id,owner_id,template_id,name,configuration) values(p_id,auth.uid(),p_template,trim(p_name),p_configuration)
 on conflict(id) do update set name=excluded.name, configuration=excluded.configuration, updated_at=now();
 insert into public.botgen_audit(actor_id,bot_id,action) values(auth.uid(),p_id,case when existing.id is null then 'created' else 'configured' end);
 return p_id;
end$$;
create function public.botgen_delete(p_id uuid) returns void
language plpgsql security definer set search_path=public as $$
begin
 if not public.botgen_is_owner() then raise exception 'Permission denied' using errcode='42501';end if;
 delete from public.botgen_bots where id=p_id and owner_id=auth.uid();
 if found then insert into public.botgen_audit(actor_id,bot_id,action) values(auth.uid(),p_id,'deleted');end if;
end$$;
revoke all on function public.botgen_is_owner(),public.botgen_save(uuid,text,text,jsonb),public.botgen_delete(uuid) from public,anon,authenticated,service_role;
grant execute on function public.botgen_is_owner(),public.botgen_save(uuid,text,text,jsonb),public.botgen_delete(uuid) to authenticated;
